#!/usr/bin/env node
// Bundle the CSS entrypoint so the app loads one stylesheet instead of
// issuing ~60 @import requests. `public/style.css` stays the modular source
// (one @import per feature/plugin), while `public/style.bundle.css` is the
// generated, self-contained runtime artifact that index.html references.
const { readFileSync, writeFileSync } = require("node:fs");
const path = require("node:path");

const root = path.resolve(__dirname, "..");
const publicDir = path.join(root, "public");
const entry = path.join(publicDir, "style.css");
const out = path.join(publicDir, "style.bundle.css");

const IMPORT_RE = /@import\s+url\(\s*"([^"]+)"\s*\)\s*;/g;

function inlineImports(absolutePath, stack) {
  const source = readFileSync(absolutePath, "utf8");
  return source.replace(IMPORT_RE, (_, spec) => {
    const target = path.resolve(path.dirname(absolutePath), spec);
    if (stack.includes(target)) {
      throw new Error(`Circular @import detected: ${target}`);
    }
    // Preserve the imported file's content, then guarantee exactly one
    // trailing newline so adjacent inlined blocks never run together.
    const content = inlineImports(target, [...stack, target]).trim();
    return `\n/* --- inlined: ${spec} --- */\n${content}\n`;
  });
}

const bundled = inlineImports(entry, [entry]);
const banner =
  "/* Generated by scripts/bundle-css.js from style.css — do not edit. */\n";
writeFileSync(out, `${banner}${bundled}\n`);

console.log(`[bundle-css] ${entry} -> ${out}`);
